def test_mutation_engine_bit_flip():
    engine = MutationEngine()
    data = b"hello world"
    mutated = engine.mutate(data, MutationStrategy.BIT_FLIP)
    assert mutated != data
    assert len(mutated) == len(data)

def test_mutation_engine_arithmetic():
    engine = MutationEngine()
    data = b"\x00\x00\x00"
    mutated = engine.mutate(data, MutationStrategy.ARITHMETIC)
    assert mutated != data
    assert len(mutated) == len(data)

def test_mutation_engine_havoc_with_dict(dictionary_file):
    engine = MutationEngine(dictionary_path=dictionary_file)
    data = b"base_data"
    # Run multiple times to ensure the 'dict' branch of havoc is hit
    mutated_found_dict = False
    for _ in range(100):
        mutated = engine.mutate(data, MutationStrategy.HAVOC)
        if b"TOKEN" in mutated:
            mutated_found_dict = True
            break
    assert mutated_found_dict, "Havoc mutation should eventually use dictionary tokens"

def test_mutation_engine_empty_input():
    engine = MutationEngine()
    assert engine.mutate(b"", MutationStrategy.BIT_FLIP) == b"\x00"

