def test_crash_triager_deduplication(temp_work_dir):
    triager = CrashTriager(temp_work_dir)
    input_data = b"crash_payload"
    stderr = "SIGSEGV: segmentation fault at 0x41414141"
    
    # First occurrence
    cat1 = triager.triage(input_data, stderr)
    assert cat1 == "SIGSEGV_MEMORY_CORRUPTION"
    
    # Duplicate occurrence
    cat2 = triager.triage(input_data, stderr)
    assert cat2 is None

def test_crash_triager_categories(temp_work_dir):
    triager = CrashTriager(temp_work_dir)
    cases = [
        ("heap-buffer-overflow detected", "HEAP_BUFFER_OVERFLOW"),
        ("stack-buffer-overflow detected", "STACK_BUFFER_OVERFLOW"),
        ("SIGABRT: assertion failed", "SIGABRT_ASSERTION_FAILURE"),
        ("random error", "UNKNOWN_CRASH"),
    ]
    for stderr, expected in cases:
        assert triager.triage(b"data", stderr) == expected

