def test_orchestrator_success(mock_binary):
    orch = ExecutionOrchestrator(mock_binary, timeout_ms=1000, instrumentation=Instrumentation.NONE)
    ret, err, new_path = orch.run(b"normal_input")
    assert ret == 0
    assert err == ""

def test_orchestrator_crash(mock_binary):
    orch = ExecutionOrchestrator(mock_binary, timeout_ms=1000, instrumentation=Instrumentation.NONE)
    ret, err, new_path = orch.run(b"CRASH_NOW")
    assert ret != 0
    assert "SIGSEGV" in err

def test_orchestrator_timeout(mock_binary):
    # Create a binary that sleeps
    sleep_bin = mock_binary.parent / "sleep_bin"
    sleep_bin.write_text("#!/bin/bash\nsleep 2")
    sleep_bin.chmod(0o755)
    
    orch = ExecutionOrchestrator(sleep_bin, timeout_ms=100, instrumentation=Instrumentation.NONE)
    ret, err, new_path = orch.run(b"data")
    assert ret == -1
    assert err == "TIMEOUT"

