def test_mutation_engine_concurrency():
    """Ensure MutationEngine is thread-safe/process-safe for parallel fuzzing."""
    engine = MutationEngine()
    data = b"concurrency_test_vector"
    
    def run_mutations():
        return [engine.mutate(data, MutationStrategy.HYBRID) for _ in range(100)]

    with ProcessPoolExecutor(max_workers=4) as executor:
        futures = [executor.submit(run_mutations) for _ in range(4)]
        results = [f.result() for f in futures]
    
    # Flatten results
    all_mutations = [item for sublist in results for item in sublist]
    assert len(all_mutations) == 400
    # Ensure we didn't just get the same value 400 times
    assert len(set(all_mutations)) > 1